// GO is awaited under the registered worker-registration budget: a message the fixture never delivers ends the
// launcher by name instead of leaving it waiting on the open channel for the whole command budget; the fixture
// is told that no worker was spawned, so its cleanup is proven.
const go = await new Promise(resolve => { const timer = setTimeout(() => resolve(undefined), ${delegationPolicy.workerRegistrationMs}); process.once('message', message => { clearTimeout(timer); resolve(message); }); process.once('disconnect', () => { clearTimeout(timer); resolve(undefined); }); });
if (go?.go !== true) { console.error('isolated launcher GO unavailable'); process.exitCode = 1; if (process.connected) process.send({goUnavailable:true}, () => process.disconnect()); else process.exit(1); }
else {
const token = await prepareValidationReservationChild();
const withdraw = async () => { try { await cancelValidationReservationChild(token); } catch (error) { console.error(error); } };
const refuse = async () => {
  clearTimeout(proceedTimer);
  try { process.kill(-worker.pid, 'SIGTERM'); } catch { try { worker.kill('SIGTERM'); } catch { /* absence below is decisive */ } }
  const until = Date.now() + ${delegationPolicy.cleanupMs};
  while (!unregisteredValidationReservationChildGone(worker.pid) && Date.now() < until) await wait(10);
  if (unregisteredValidationReservationChildGone(worker.pid)) await withdraw();
  process.exitCode = 1; if (process.connected) process.disconnect();
};
await attemptValidationReservationSpawn(token);
const worker = spawn(process.execPath, ['--input-type=module', '--eval', ${JSON.stringify(code)}, String(process.pid)],
  {detached:true, stdio:validationReservationChildStdio(['ignore',1,2,'ipc']), env:validationReservationChildEnvironment(process.env)});
worker.once('spawn', async () => {
  // The spawned PID is noted on the fence before the fixture process observes the worker.
  try { await noteValidationReservationSpawn(token, worker.pid); } catch (error) { console.error(error); await refuse(); return; }
  if (process.connected) process.send({pid:worker.pid, fenced:token !== undefined});
  // The acknowledgement is awaited under the same budget: one the fixture never delivers refuses the worker.
  proceedTimer = setTimeout(async () => { console.error('isolated registration ACK unavailable'); process.removeAllListeners('message'); if (process.connected) process.send({ackUnavailable:true}); await refuse(); }, ${delegationPolicy.workerRegistrationMs});
});
worker.once('error', async error => {
  console.error(error);
  process.exitCode = 1;
  if (worker.pid === undefined) { await withdraw(); if (process.connected) { process.send({spawnFailed:true}, () => process.disconnect()); } return; }
  if (process.connected) process.disconnect();
});
process.once('message', async message => {
  clearTimeout(proceedTimer);
  if (message?.proceed !== true) { await refuse(); return; }
  try { await registerValidationReservationChild(worker.pid, token); } catch (error) { console.error(error); await refuse(); return; }
  if (worker.connected) worker.send({registered:true}); else { process.exitCode = 1; if (process.connected) process.disconnect(); }
});
worker.once('exit',()=>{if(!workerReady){clearTimeout(proceedTimer);process.exitCode=1;if(process.connected)process.disconnect();}});
worker.once('message', message=>{workerReady=message?.ready===true;if(message?.ready!==true){worker.kill('SIGTERM');process.exitCode=1;}worker.unref();if(process.connected)process.disconnect();});
}`;
  try {
    launcherPending = await prepareValidationReservationChild();
    // Marked immediately before the spawn call, so a lost launcher spawn leaves an unmarked
    // fence that resolves once this owner is proven gone.
    await attemptValidationReservationSpawn(launcherPending);
    const launcher = spawn(process.execPath, ['--input-type=module', '--eval', launcherCode], {
      cwd: process.cwd(), env: validationReservationChildEnvironment(sanitizedFixtureChildEnvironment(process.env)), stdio: validationReservationChildStdio(['ignore', fd, fd, 'ipc']),
      // The launcher is a registered child, so it owns its detached group like every executor child.
      detached: true,
    });
    launcherSpawned = launcher.pid !== undefined; launcherPid = launcher.pid;
    let registration = Promise.resolve();
    let launcherFailure: Error | undefined;
    // A message this process cannot deliver (a broken channel under a live launcher) is a launcher failure
    // by name, not a log line: the launcher's group is signalled at once while it is still this process's
    // unreaped child, so the launcher's own bounded wait is not the only thing ending it.
    const launcherUndeliverable = (message: string, error: Error): void => {
      launcherFailure ??= new Error(`${message}: ${error.message}`);
      if (launcher.exitCode === null && launcher.signalCode === null) { try { process.kill(-launcher.pid!, 'SIGTERM'); } catch { try { launcher.kill('SIGTERM'); } catch { /* the exit below is decisive */ } } }
    };
    const acknowledge = (proceed: boolean) => {
      if (!launcher.connected) return;
      launcher.send({proceed}, error => { if (error) launcherUndeliverable('isolated fixture registration ACK undeliverable', error); });
    };
    launcher.on('message', value => {
      const message = value as {pid?: unknown; fenced?: unknown; spawnFailed?: unknown; goUnavailable?: unknown; ackUnavailable?: unknown};
      // A failed spawn call created no worker; the launcher withdrew the fence it owns.
      if (message.spawnFailed === true) { workerSpawnFailed = true; return; }
      // A launcher whose bounded wait for GO ended spawned no worker; one whose wait for the acknowledgement
      // ended refused the worker it spawned and withdraws its fence once that worker is proven absent.
      if (message.goUnavailable === true) { launcherGoUnavailable = true; return; }
      if (message.ackUnavailable === true) { launcherAckUnavailable = true; return; }
      if (workerPid !== undefined || typeof message.pid !== 'number') return;
      workerPid = message.pid; workerFenced = message.fenced === true;
      registration = Promise.resolve().then(() => {
        // Transient kernel observation failures are retried with the registered policy
        // before the worker is refused; a definitive non-leader observation is refused at once.
        let observed: ProcessIdentity;
        try { observed=observeWithBoundedRetry(()=>observeValidationReservationChild(workerPid!)); }
        catch (error) {
          if (workerFenced) throw error;
          // No reservation is borrowed, so no fence protects anything: an unavailable observation
          // is advisory, the worker runs, and cleanup falls back to the best-effort group signal.
          observationDegraded = true; console.error(error); return;
        }
        if(observed.pgid!==observed.pid)throw new Error('isolated worker group identity unavailable');
        workerIdentity=observed;
      }).then(() => acknowledge(true), (error: unknown) => {
        // The launcher terminates the refused worker and withdraws the fence it owns once the
        // worker's PID and whole group are proven absent; a live or unobservable worker keeps it.
        acknowledge(false); console.error(error);
      });
    });
    const launcherExit = new Promise<void>((resolve, reject) => {
      launcher.once('error', reject);
      launcher.once('exit', code => { void registration.then(() => code === 0 && workerPid ? resolve() : reject(launcherFailure ?? new Error(launcherGoUnavailable ? 'isolated fixture launcher GO unavailable' : launcherAckUnavailable ? 'isolated fixture registration ACK unavailable' : workerSpawnFailed ? 'isolated fixture worker spawn failed' : 'isolated fixture launcher failed'))); });
    });
    launcherExit.catch(() => { /* awaited below; an early rejection must not be unhandled */ });
    if (launcher.pid !== undefined) {
      // Noted and registered exactly like an executor child before it proceeds; a refused note or
      // registration terminates the launcher with its group and the fence is withdrawn only once
      // proven absent.
      try { await noteValidationReservationSpawn(launcherPending, launcher.pid); await registerValidationReservationChild(launcher.pid, launcherPending); }
      catch (error) {
        launcherRegistrationRefused = true;
        try { process.kill(-launcher.pid, 'SIGTERM'); } catch { try { launcher.kill('SIGTERM'); } catch { /* absence below is decisive */ } }
        throw error;
      }
      if (launcher.connected) launcher.send({go:true}, error => { if (error) launcherUndeliverable('isolated fixture launcher GO undeliverable', error); });
    }
    await launcherExit;
    // The 58-case routes integration performs real target executions and
    // exceeded 120 s twice at case 46 under the independent Claude host.
    // Keep its bounded fixture budget separate from production command limits.
    // Expanded authority controls exhausted 360 s in three recorded Lab runs.
    // Use the existing 450 s outer budget minus 30 s cleanup; concurrent
    // execution remains capped at 540 s and the original remaining deadline.
    const budgetStartedAt=Date.now();
    const budgetMs = file.endsWith('/finding-identity-lineage-smoke.js') ? 300_000
      : file.endsWith('/verify-review-epoch-certification-continuity.mjs') ? reviewEpochFixtureBudgetMs(process.env,budgetStartedAt)
      : file.endsWith('/verify-managed-inventory-critic-import.mjs') ? managedCriticFixtureBudgetMs(process.env,budgetStartedAt) : 120_000;
    const deadline = budgetStartedAt + budgetMs;
    if(file.endsWith('/verify-review-epoch-certification-continuity.mjs')) process.stdout.write(`REVIEW_EPOCH_FIXTURE_BUDGET ${JSON.stringify({budgetMs,deadline,outerEnvelope:process.env[epochBudget.environmentKey]??null})}\n`);
    let workerExitedWithoutOutcome = false;
    while (!existsSync(outcome) && Date.now() < deadline) {
      if (workerIdentity && validationReservationGroupIsAbsent(workerIdentity.pgid)) {
        // The worker publishes its outcome before exit. Recheck after observing
        // whole-group absence so a concurrent publication remains authoritative.
        if (!existsSync(outcome)) workerExitedWithoutOutcome = true;
        break;
      }
      await new Promise(resolve => setTimeout(resolve, 50));
    }
    process.stdout.write(readFileSync(output, 'utf8')); outputWritten = true;
    if (!existsSync(outcome)) throw new Error(workerExitedWithoutOutcome
      ? 'isolated Finding fixture worker exited without outcome' : 'isolated Finding fixture timed out');
    const result = JSON.parse(readFileSync(outcome, 'utf8')) as { code: number };
    if (result.code !== 0) throw new Error(`isolated Finding fixture failed with exit ${result.code}`);
    return true;
  } catch(error) { fixtureFailure=error;throw error; } finally {
    // The original workload deadline is unchanged. Cleanup has its separately registered bounded
    // window and may signal only the recorded own worker group under the controller's own rule: its
    // leader still observed with the recorded identity, or absent while that group persists. A group
    // that persists once the outcome is published, or without one, is signalled at once and SIGKILL
    // follows at the half-budget point, so a lingering same-group descendant is cleared instead of
    // turning a published outcome into a refusal.
    const signalOwnWorker=(signal:'SIGTERM'|'SIGKILL')=>{
      if(!workerIdentity||workerIdentity.pid<=1||!validationReservationOwnedGroupSignalTarget(workerIdentity))return;
      try{process.kill(-workerIdentity.pgid,signal);}catch{/* Absence below is decisive. */}
    };
    if(workerIdentity&&!validationReservationGroupIsAbsent(workerIdentity.pgid))signalOwnWorker('SIGTERM');
    if(observationDegraded&&workerPid!==undefined&&!existsSync(outcome)){try{process.kill(-workerPid,'SIGTERM');}catch{/* best effort without an observed identity */}}
    const cleanupUntil=Date.now()+delegationPolicy.cleanupMs;
    while(workerIdentity&&!validationReservationGroupIsAbsent(workerIdentity.pgid)&&Date.now()<cleanupUntil){
      if(Date.now()>=cleanupUntil-delegationPolicy.cleanupMs/2)signalOwnWorker('SIGKILL');
      await new Promise(resolve=>setTimeout(resolve,20));
    }
    if (!outputWritten && existsSync(output)) process.stdout.write(readFileSync(output, 'utf8'));
    let cleanupFailure: unknown;
    // The launcher fence follows the executor's rule: a spawn call that created no launcher is
    // withdrawn at once; a refused launcher registration is withdrawn only once the launcher's PID
    // and whole group are proven absent, and a live or unobservable launcher keeps the fence.
    if (!launcherSpawned) {try{await cancelValidationReservationChild(launcherPending);}catch(error){cleanupFailure=error;}}
    else if (launcherRegistrationRefused && launcherPid !== undefined) {
      const until=Date.now()+delegationPolicy.cleanupMs;
      while(!unregisteredValidationReservationChildGone(launcherPid)&&Date.now()<until)await new Promise(resolve=>setTimeout(resolve,10));
      if(unregisteredValidationReservationChildGone(launcherPid)){try{await cancelValidationReservationChild(launcherPending);launcherWithdrawn=true;}catch(error){cleanupFailure=error;}}
    }
    closeSync(fd);
    // A spawn call the launcher reported as failed created no worker, a launcher that reported its
    // bounded wait for GO ended spawned none, and a launcher refused before it received GO and then
    // proven absent spawned none either, so nothing remains to prove absent; an unobserved or
    // still-present worker group keeps the cleanup unproven.
    if(cleanupFailure||launcherSpawned&&!observationDegraded&&!workerSpawnFailed&&!launcherGoUnavailable&&!launcherWithdrawn&&(!workerIdentity||!validationReservationGroupIsAbsent(workerIdentity.pgid))){
      const primary=fixtureFailure===undefined?'':(fixtureFailure instanceof Error?fixtureFailure.message:String(fixtureFailure))+'; ';
      throw new Error(primary+'isolated Finding fixture cleanup unproven; retained '+scratch+(cleanupFailure?'; '+String(cleanupFailure):''),{cause:fixtureFailure??cleanupFailure});
    }
    rmSync(scratch, { recursive: true, force: true });
  }
}

import { validationReservationChildEnvironment, validationReservationChildStdio } from '../core/validation-reservation-delegation.js';
import { randomUUID } from 'node:crypto';
import { spawn } from 'node:child_process';
import { closeSync, openSync, unlinkSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { generateEd25519KeyPair } from '../core/authority-signing.js';
import {
  signNativeReviewInvocationAttestation,
  type NativeReviewBrokerRegistration,
} from '../core/native-review-attestation.js';
import { resetSessionIdForTest } from '../core/owner-session.js';
import { getSessionIdentity } from '../core/owner-session.js';
import {
  issueNativeReviewEvidenceBinding,
  observeNativeHostProcess,
  type NativeHostProcessObservation,
} from '../core/native-review-evidence.js';
import { verifyCurrentReviewerDispatchBinding } from '../core/review-run.js';
import {
  DELIVERY_REVIEW_LANE,
  verifyCurrentDeliveryReviewDispatch,
} from '../core/delivery-review-authority.js';
import type { StoryStore } from '../core/store.js';
import { sanitizedFixtureChildEnvironment } from './fixture-environment.js';

const keys = generateEd25519KeyPair();
const CLI = fileURLToPath(new URL('../cli.js', import.meta.url));

export function nativeReviewFixtureBrokers(): NativeReviewBrokerRegistration[] {
  return [
    { brokerId: 'fixture-codex-broker', adapterId: 'codex-fixture-adapter', host: 'codex', publicKey: keys.publicKey },
    { brokerId: 'fixture-claude-broker', adapterId: 'claude-fixture-adapter', host: 'claude', publicKey: keys.publicKey },
  ];
}

/**
 * Resolve the host a fixture identity may legitimately claim.
 *
 * `issueNativeReviewEvidenceBinding` vetoes any binding whose declared host
 * disagrees with the observed Codex/Claude process ancestry — that veto is real
 * product behaviour and these smokes must not weaken or bypass it. A fixture
 * that hard-coded one host therefore only passed under that host and failed
 * under the other, purely because of who ran `lattice validate`.
 *
 * So the fixture declares the host it is ACTUALLY running under whenever the
 * ancestry is observable, and falls back to `codex` only when no provider
 * ancestry is visible (no process table, or a non-provider parent) — the case
 * where the veto's ancestry check cannot fire anyway. Mixed ancestry is left
 * alone: that is an unconditional cross-provider veto the smokes should keep
 * observing.
 */
export function nativeReviewFixtureAmbientHost(
  observe: () => NativeHostProcessObservation | null = observeNativeHostProcess,
): 'codex' | 'claude' {
  return resolveNativeReviewFixtureAmbientHost(observe).host;
}

/**
 * Same resolution as {@link nativeReviewFixtureAmbientHost}, but also reports
 * whether a single provider ancestry was genuinely OBSERVED.
 *
 * The distinction matters for negative controls. `host` is `'codex'` both when
 * ancestry really is Codex and when ancestry is unobservable (no process table,
 * a non-provider parent, or mixed families) — but the ancestry veto can only
 * fire in the first case. A test that asserts "the non-ambient host must be
 * vetoed" is therefore only valid when `observed` is true; otherwise NEITHER
 * host trips the veto and the declared host is accepted as-is.
 */
export function resolveNativeReviewFixtureAmbientHost(
  observe: () => NativeHostProcessObservation | null = observeNativeHostProcess,
): { host: 'codex' | 'claude'; observed: boolean } {
  let seen: NativeHostProcessObservation | null = null;
  try {
    seen = observe();
  } catch {
    return { host: 'codex', observed: false };
  }
  // Mixed families are an unconditional veto for EVERY declared host, so they
  // are not a usable "ambient host" either.
  if (!seen || seen.mixedProviderFamilies) return { host: 'codex', observed: false };
  return { host: seen.host === 'claude' ? 'claude' : 'codex', observed: true };
}

/**
 * Native-review smokes must not inherit authority from whichever host happens
 * to execute the validation command.  This fixture identity is deliberately
 * explicit and is only the host-side precursor used to create a signed
 * dispatch; the one-shot broker attestation below remains required for formal
 * evidence closeout. Only the host LABEL follows the ambient ancestry (see
 * {@link nativeReviewFixtureAmbientHost}); no authority is inherited.
 */
export function nativeReviewFixtureHostEnvironment(
  agent: string,
  host: 'codex' | 'claude' = nativeReviewFixtureAmbientHost(),
  sessionId = `native-review-fixture-host-${randomUUID()}`,
): Record<string, string> {
  return {
    PROOF_OR_STOP_SESSION_ID: sessionId,
    PROOF_OR_STOP_AGENT: agent,
    PROOF_OR_STOP_OWNER_SESSION_ADAPTER_PROVIDER: host === 'claude' ? 'claude-code' : 'codex',
    PROOF_OR_STOP_OWNER_SESSION_ADAPTER_TASK: `native-review-fixture:${agent}`,
    PROOF_OR_STOP_OWNER_SESSION_ADAPTER_AGENT: agent,
    ...(host === 'claude' ? { CLAUDE_CODE_SESSION_ID: sessionId } : {}),
  };
}

export function withNativeReviewFixtureHostIdentity<T>(args: {
  agent: string;
  host?: 'codex' | 'claude';
  invoke: () => T;
}): T {
  const environment = nativeReviewFixtureHostEnvironment(args.agent, args.host);
  const envKeys = Object.keys(environment);
  const previous = Object.fromEntries(envKeys.map(key => [key, process.env[key]]));
  try {
    Object.assign(process.env, environment);
    resetSessionIdForTest();
    return args.invoke();
  } finally {
    resetSessionIdForTest();
    for (const key of envKeys) {
      const value = previous[key];
      if (value === undefined) delete process.env[key];
      else process.env[key] = value;
    }
  }
}

function fixtureInvocation(args: {
  root: string;
  store: StoryStore;
  storyId: string;
  agent: string;
  reviewRunId: string;
}) {
  const story = args.store.readStory(args.storyId);
  if (!story?.currentReviewRound) throw new Error('native review fixture requires an active review round');
  const run = args.store.readReviewRuns(args.storyId).runs.find(row => row.reviewRunId === args.reviewRunId);
  const dispatch = verifyCurrentReviewerDispatchBinding({
    store: args.store,
    storyId: args.storyId,
    lane: args.agent,
    reviewRound: story.currentReviewRound,
    projectRoot: args.root,
    reviewPurpose: run?.reviewPurpose, inventoryBinding: run?.inventoryBinding,
  });
  if (!dispatch.ok) throw new Error(`native review fixture has no signed dispatch binding: ${dispatch.reason}`);
  const broker = nativeReviewFixtureBrokers().find(candidate => candidate.host === dispatch.binding.hostRenderHost);
  if (!broker) throw new Error(`native review fixture has no broker for ${dispatch.binding.hostRenderHost}`);
  const writerSessionId = `native-review-fixture-${randomUUID()}`;
  const now = Date.now();
  const attestation = signNativeReviewInvocationAttestation({
    schemaVersion: 'lattice.native_review_invocation_attestation.v1',
    brokerId: broker.brokerId,
    adapterId: broker.adapterId,
    host: broker.host,
    storyId: args.storyId,
    agent: args.agent,
    lane: args.agent,
    reviewRunId: args.reviewRunId,
    writerSessionId,
    dispatchPromptDigest: dispatch.binding.dispatchPromptDigest,
    dispatchBindingDigest: dispatch.binding.dispatchBindingDigest,
    hostRenderIdentityDigest: dispatch.binding.hostRenderIdentityDigest,
    invocationNonce: randomUUID(),
    issuedAt: new Date(now).toISOString(),
    expiresAt: new Date(now + 60_000).toISOString(),
  }, keys.privateKey);
  return {
    attestation,
    env: nativeReviewFixtureHostEnvironment(args.agent, broker.host, writerSessionId),
  };
}

export async function runBrokeredNativeReviewCli(args: {
  root: string;
  store: StoryStore;
  storyId: string;
  agent: string;
  reviewRunId: string;
  command: 'review_pass_set' | 'finding_add';
  payload: Record<string, unknown>;
  /** Test-only process controls; broker identity and descriptor remain authoritative. */
  env?: NodeJS.ProcessEnv;
}): Promise<string> {
  const invocation = fixtureInvocation(args);
  return new Promise<string>((resolvePromise, reject) => {
    const child = spawn(process.execPath, [CLI, args.command, JSON.stringify(args.payload)], {
      cwd: args.root,
      env: validationReservationChildEnvironment({
        ...sanitizedFixtureChildEnvironment({ ...process.env, ...args.env }),
        ...invocation.env,
        LATTICE_NATIVE_REVIEW_ATTESTATION_FD: '3',
      }),
      stdio: validationReservationChildStdio(['ignore', 'pipe', 'pipe', 'pipe']),
    });
    let stdout = '';
    let stderr = '';
    child.stdout!.setEncoding('utf8');
    child.stderr!.setEncoding('utf8');
    child.stdout!.on('data', chunk => { stdout += String(chunk); });
    child.stderr!.on('data', chunk => { stderr += String(chunk); });
    child.once('error', reject);
    child.once('exit', code => {
      if (code === 0) resolvePromise(stdout);
      else reject(new Error(`${args.command} exited ${code}: ${stderr}`));
    });
    const brokerPipe = child.stdio[3] as NodeJS.WritableStream;
    brokerPipe.write(`${JSON.stringify(invocation.attestation)}\n`);
    brokerPipe.end();
  });
}

/**
 * Execute one direct handler closeout under the same signed, one-shot
 * descriptor boundary used by an integrated Codex/Claude host adapter. The
 * fixture owns the broker private key; ordinary production CLI exposes no
 * issuer and receives only the inherited descriptor.
 */
export function withBrokeredNativeReviewInvocation<T>(args: {
  root: string;
  store: StoryStore;
  storyId: string;
  agent: string;
  reviewRunId: string;
  invoke: () => T;
}): T {
  const invocation = fixtureInvocation(args);
  const path = join(args.root, `.native-review-fixture-${randomUUID()}.json`);
  writeFileSync(path, `${JSON.stringify(invocation.attestation)}\n`, { mode: 0o600 });
  const fd = openSync(path, 'r');
  const envKeys = [
    'LATTICE_NATIVE_REVIEW_ATTESTATION_FD',
    'PROOF_OR_STOP_SESSION_ID',
    'PROOF_OR_STOP_AGENT',
    'PROOF_OR_STOP_OWNER_SESSION_ADAPTER_PROVIDER',
    'PROOF_OR_STOP_OWNER_SESSION_ADAPTER_TASK',
    'PROOF_OR_STOP_OWNER_SESSION_ADAPTER_AGENT',
    'CLAUDE_CODE_SESSION_ID',
  ] as const;
  const previous = Object.fromEntries(envKeys.map(key => [key, process.env[key]]));
  try {
    process.env.LATTICE_NATIVE_REVIEW_ATTESTATION_FD = String(fd);
    Object.assign(process.env, invocation.env);
    resetSessionIdForTest();
    return args.invoke();
  } finally {
    resetSessionIdForTest();
    for (const key of envKeys) {
      const value = previous[key];
      if (value === undefined) delete process.env[key];
      else process.env[key] = value;
    }
    closeSync(fd);
    unlinkSync(path);
  }
}

export function issueBrokeredNativeReviewBinding(args: {
  root: string;
  store: StoryStore;
  storyId: string;
  agent: string;
  reviewRunId: string;
}) {
  const story = args.store.readStory(args.storyId);
  if (!story?.currentReviewRound) throw new Error('native review fixture requires an active review round');
  const dispatch = verifyCurrentReviewerDispatchBinding({
    store: args.store,
    storyId: args.storyId,
    lane: args.agent,
    reviewRound: story.currentReviewRound,
    projectRoot: args.root,
  });
  if (!dispatch.ok) throw new Error(`native review fixture has no signed dispatch binding: ${dispatch.reason}`);
  return withBrokeredNativeReviewInvocation({
    ...args,
    invoke: () => issueNativeReviewEvidenceBinding({
      projectRoot: args.root,
      storyId: args.storyId,
      agent: args.agent,
      lane: args.agent,
      reviewRunId: args.reviewRunId,
      identity: getSessionIdentity(),
      dispatch: dispatch.binding,
    }),
  });
}

function deliveryFixtureInvocation(args: {
  root: string;
  store: StoryStore;
  storyId: string;
}) {
  const dispatch = verifyCurrentDeliveryReviewDispatch({
    store: args.store,
    storyId: args.storyId,
    projectRoot: args.root,
  });
  if (!dispatch.ok) throw new Error(`native delivery fixture has no signed dispatch binding: ${dispatch.reason}`);
  const broker = nativeReviewFixtureBrokers().find(
    candidate => candidate.host === dispatch.binding.dispatch.hostRenderHost,
  );
  if (!broker) throw new Error(`native delivery fixture has no broker for ${dispatch.binding.dispatch.hostRenderHost}`);
  const writerSessionId = `native-delivery-fixture-${randomUUID()}`;
  const now = Date.now();
  return {
    attestation: signNativeReviewInvocationAttestation({
      schemaVersion: 'lattice.native_review_invocation_attestation.v1',
      brokerId: broker.brokerId,
      adapterId: broker.adapterId,
      host: broker.host,
      storyId: args.storyId,
      agent: DELIVERY_REVIEW_LANE,
      lane: DELIVERY_REVIEW_LANE,
      reviewRunId: dispatch.binding.invocationId,
      writerSessionId,
      dispatchPromptDigest: dispatch.binding.dispatch.dispatchPromptDigest,
      dispatchBindingDigest: dispatch.binding.dispatch.dispatchBindingDigest,
      hostRenderIdentityDigest: dispatch.binding.dispatch.hostRenderIdentityDigest,
      invocationNonce: randomUUID(),
